//! Levenberg-Marquardt solver with dense, band, and sparse backends.
//!
//! The solver minimizes a sum-of-squares cost function using the
//! Gauss-Newton approximation with adaptive LM damping. Problems
//! implement `LmProblem` (usually auto-generated by `#[arael(root)]`),
//! and backends implement `LmSolver`.
//!
//! This is intentionally a simple, predictable solver. A more
//! sophisticated implementation could use adaptive strategies such as
//! gain-ratio-based lambda updates, trust region methods, or even
//! machine-learned parameter selection and termination criteria.
//! The current design favors transparency and ease of tuning via
//! [`LmConfig`](crate::simple_lm::LmConfig) over automatic sophistication.
//!
//! # Example
//!
//! ```ignore
//! // After defining your model with #[arael(root)]:
//! let mut params = Vec::new();
//! path.serialize64(&mut params);
//!
//! let config = arael::simple_lm::LmConfig {
//!     verbose: true,
//!     ..Default::default()
//! };
//!
//! // Dense solver:
//! let result = arael::simple_lm::solve(&params, &mut path, &config);
//!
//! // Band solver (for block-tridiagonal systems, kd = half-bandwidth):
//! let result = arael::simple_lm::solve_band(&params, 11, &mut path, &config);
//!
//! // Sparse solver (faer, pure Rust):
//! let result = arael::simple_lm::solve_sparse_faer(&params, &mut path, &config);
//!
//! path.deserialize64(&result.x);
//! println!("cost: {} -> {} in {} iterations",
//!     result.start_cost, result.end_cost, result.iterations);
//! ```

use crate::utils::Float;
use std::fmt;
use std::time::Duration;
#[cfg(target_arch = "wasm32")]
use web_time::Instant;
#[cfg(not(target_arch = "wasm32"))]
use std::time::Instant;

/// Format a float like C's `%g` — 6 significant digits, uses the shorter of
/// fixed or scientific notation, strips trailing zeros.
struct G<T>(T);

impl fmt::Display for G<f64> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let v = self.0;
        if v == 0.0 {
            return f.write_str("0");
        }
        // C's %g: use %e when exponent < -4 or >= precision (6)
        let exp = v.abs().log10().floor() as i32;
        if !(-4..6).contains(&exp) {
            // Scientific: 6 significant digits means precision = 5 after the leading digit
            let s = format!("{:.5e}", v);
            // Trim trailing zeros in mantissa
            if let Some(pos) = s.find('e') {
                let (mantissa, exponent) = s.split_at(pos);
                let trimmed = mantissa.trim_end_matches('0').trim_end_matches('.');
                write!(f, "{}{}", trimmed, exponent)
            } else {
                f.write_str(&s)
            }
        } else {
            // Fixed: number of decimal places = max(0, 5 - exp)
            let decimals = (5 - exp).max(0) as usize;
            let s = format!("{:.*}", decimals, v);
            if s.contains('.') {
                let trimmed = s.trim_end_matches('0').trim_end_matches('.');
                f.write_str(trimmed)
            } else {
                f.write_str(&s)
            }
        }
    }
}

impl fmt::Display for G<f32> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", G(self.0 as f64))
    }
}


/// Fixed-size dispatch threshold. Systems up to this size use compile-time
/// fixed-size matrices for efficiency; larger systems use dynamic allocation.
pub const FIXED_SIZE_THRESHOLD: usize = 9;

// ---------------------------------------------------------------------------
// LM solver types
// ---------------------------------------------------------------------------

/// Configuration for the Levenberg-Marquardt solver.
///
/// Choosing good parameters depends heavily on the problem structure:
///
/// - **Well-conditioned, near minimum** (e.g. re-solving after a small
///   perturbation): use small `initial_lambda` (1e-6), tight precision, few
///   iterations. The Gauss-Newton step is nearly optimal.
///
/// - **Far from minimum** (e.g. first solve from a rough initial guess):
///   use larger `initial_lambda` (1e-3 or higher) so early steps are more
///   gradient-descent-like and don't overshoot. Increase `max_iters`.
///
/// - **Ill-conditioned / many local minima** (e.g. SLAM with outliers):
///   use graduated optimization (multiple passes with increasing constraint
///   weights) rather than tuning LM parameters. The robust cost function
///   handles outliers; LM just needs enough iterations per pass.
///
/// - **Interactive / real-time** (e.g. sketch editor drag): use small
///   `initial_lambda` (1e-6), moderate `max_iters` (50-100), loose precision.
///   Speed matters more than the last decimal of convergence.
///
/// The defaults are a reasonable middle ground. For critical applications,
/// experiment with the parameters on representative problem instances.
#[derive(Clone)]
pub struct LmConfig<T: Float> {
    /// Absolute cost improvement threshold. A step counts as "small" when
    /// the cost decrease is below this OR the relative improvement is
    /// below `rel_precision` (either criterion suffices -- abs alone can
    /// stop a solve whose cost is tiny, rel alone one that plateaus at a
    /// large cost). After `patience` consecutive small steps, the solver
    /// terminates.
    pub abs_precision: T,
    /// Relative cost improvement threshold. A step counts as "small" when
    /// `(old_cost - new_cost) / old_cost < rel_precision` (OR the absolute
    /// criterion above). Note the badly-scaled-problem hazard: a solve at
    /// cost 1e9 improving 1e4 per step is relatively small and will stop;
    /// rescale the problem or lower `rel_precision`.
    pub rel_precision: T,
    /// Maximum number of LM iterations (including inner damping retries).
    pub max_iters: usize,
    /// Minimum iterations before termination is allowed. Ensures the solver
    /// makes at least this many accepted steps before checking convergence.
    pub min_iters: usize,
    /// Number of consecutive "small improvement" steps before stopping.
    /// Higher values make the solver more conservative about terminating.
    pub patience: usize,
    /// Initial damping parameter lambda. Small values (1e-6) behave like
    /// Gauss-Newton (fast near minimum, may overshoot far away). Large
    /// values (1e-1) behave like gradient descent (slow but stable). The
    /// solver adapts lambda automatically during the solve.
    pub initial_lambda: T,
    /// Stop immediately when cost drops to or below this value. Set to 0.0
    /// to disable (only terminate via precision/patience). Useful when you
    /// know the target cost (e.g. constraint satisfaction where 0 is perfect).
    pub cost_threshold: T,
    /// Minimum damping lambda: LM never decreases lambda below this after
    /// an accepted step (clamped from below to machine epsilon). The
    /// default 1e-12 effectively means "no floor" for well-posed problems.
    /// Raise it (e.g. 1e-6) for problems with gauge freedom or otherwise
    /// near-singular Hessians -- bundle adjustment with its 7-DOF gauge is
    /// the canonical case -- where near-zero damping produces
    /// non-positive-definite damped systems and catastrophic Gauss-Newton
    /// overshoots along the near-null directions.
    pub lambda_floor: T,
    /// Print per-iteration cost, lambda, and timing to stderr. Very useful
    /// for understanding how the solver behaves with a given parameter set --
    /// check the output to validate convergence and tune the config.
    pub verbose: bool,
    /// The damping-schedule strategy: how lambda evolves across the solve
    /// (see [`LambdaDriver`]). Defaults to [`DefaultLambdaDriver`], the
    /// classic fixed-multiplier schedule; set another (e.g.
    /// [`NielsenLambdaDriver`]) with [`LmConfig::with_driver`]. The driver
    /// reads `initial_lambda` and `lambda_floor` from this config at solve
    /// start, so those two fields configure whichever driver is in place.
    pub driver: Box<dyn LambdaDriver<T>>,
    /// Gather per-phase wall-clock timing. When `true`, [`LmResult::timing`]
    /// is `Some(LmTiming)`; when `false` (the default) it is `None` and the
    /// solver never reads the clock -- zero overhead. Enable it to profile
    /// where a solve spends its time (assembly, factorization, cost
    /// evaluation, re-centering); the first assembly and first factorization
    /// are recorded separately because they also establish the sparsity
    /// pattern and symbolic factorization.
    pub gather_timing: bool,
}

impl<T: Float> Default for LmConfig<T> {
    fn default() -> Self {
        LmConfig {
            abs_precision: T::from(1e-6).unwrap(),
            rel_precision: T::from(1e-4).unwrap(),
            max_iters: 100,
            min_iters: 5,
            patience: 3,
            initial_lambda: T::from(1e-4).unwrap(),
            cost_threshold: T::zero(),
            lambda_floor: default_lambda_floor::<T>(),
            verbose: false,
            driver: Box::new(DefaultLambdaDriver::default()),
            gather_timing: false,
        }
    }
}

impl<T: Float> LmConfig<T> {
    /// Set the damping-schedule driver, returning the config for chaining:
    /// `LmConfig { initial_lambda: 1e-6, ..Default::default() }
    /// .with_driver(NielsenLambdaDriver::default())`. The driver still
    /// reads `initial_lambda` / `lambda_floor` from this config.
    pub fn with_driver(mut self, driver: impl LambdaDriver<T> + 'static) -> Self {
        self.driver = Box::new(driver);
        self
    }
}

// ---------------------------------------------------------------------------
// LmProblem trait — object implementing cost + gradient/hessian
// ---------------------------------------------------------------------------

/// Error when a block's indices exceed the declared bandwidth.
#[derive(Debug)]
pub struct BandError {
    /// Row index of the offending element.
    pub row: usize,
    /// Column index of the offending element.
    pub col: usize,
    /// Declared half-bandwidth that was exceeded.
    pub kd: usize,
}

impl std::fmt::Display for BandError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "band overflow: element ({}, {}) exceeds bandwidth kd={}", self.row, self.col, self.kd)
    }
}

/// Interface for optimization problems.
///
/// Parameter round trip of an `#[arael(root)]` model: flatten the model's
/// parameters into a vector and write an optimized vector back. Implemented
/// by the macro for every root (it is the part that needs generated code --
/// block-index assignment on serialize, extended-model hooks on
/// deserialize); the solve entry points on [`LmProblem`] are default
/// methods gated on it, so implementing this is what gives a type
/// `solve_with` / `solve_dense` / `solve_sparse`.
pub trait RootProblem<T: Float> {
    /// Flatten the optimizable parameters into `data` and assign the
    /// Hessian block indices. The initial guess for a solve.
    fn serialize(&mut self, data: &mut Vec<T>);
    /// Write an optimized parameter vector back into the model
    /// (including extended-model state). Mandatory after a solve over a
    /// raw vector; the `solve_*` entry points call it for you.
    fn deserialize(&mut self, data: &[T]);
    /// Parameter index ranges of fields marked `#[arael(root,
    /// eliminate_first(field))]`: small mutually uncoupled blocks
    /// (landmark-style entities) that a sparse backend may eliminate
    /// first (see [`SparseFaer::with_eliminate_first`]). Empty by
    /// default; the macro overrides it for marked fields.
    fn elimination_hint(&self) -> std::vec::Vec<std::ops::Range<usize>> {
        std::vec::Vec::new()
    }
    /// Entity parameter blocks as `(offset, width)` spans of the flat
    /// parameter vector, one per live entity, in serialize order --
    /// read from each entity's `SelfBlock` indices, so it is valid only
    /// after [`serialize`](Self::serialize). The macro overrides this;
    /// the default is empty. See [`block_partition_from_spans`] for
    /// turning spans into a full partition.
    fn param_block_spans(&self) -> std::vec::Vec<(u32, u32)> {
        std::vec::Vec::new()
    }
}

/// Scalar-coordinate -> CSC-position resolver over a tile-expanded
/// pattern built by [`csc_from_cells`], memoized per run of same-cell
/// coordinates (one cell lookup per contributing block object). Owns
/// its lookup tables, so it has no lifetime ties to the matrix.
#[derive(Clone)]
pub struct ScalarCscResolver {
    col_ptr: std::vec::Vec<usize>,
    row_part: std::vec::Vec<usize>,
    blk_of: std::vec::Vec<u32>,
    /// sorted (block_col << 32 | block_row) keys of the stored cells
    keys: std::vec::Vec<u64>,
    /// per stored cell: scalar-row prefix of the tiles above it within
    /// its block column (column-independent)
    prefix: std::vec::Vec<usize>,
    memo_key: u64,
    memo_prefix: usize,
    memo_row_start: usize,
}

impl ScalarCscResolver {
    /// Position of scalar (row, col) in the tile-expanded CSC. Panics
    /// if the coordinate's cell is not part of the structure.
    #[inline]
    pub fn resolve(&mut self, i: u32, j: u32) -> usize {
        let (i, j) = (i as usize, j as usize);
        let key = ((self.blk_of[j] as u64) << 32) | self.blk_of[i] as u64;
        if key != self.memo_key {
            self.memo_key = key;
            let c = self.keys.binary_search(&key)
                .expect("coordinate outside the built pattern");
            self.memo_prefix = self.prefix[c];
            self.memo_row_start = self.row_part[self.blk_of[i] as usize];
        }
        self.col_ptr[j] + self.memo_prefix + (i - self.memo_row_start)
    }
}

/// Build a scalar CSC pattern by tile-expanding the block cells of an
/// entity partition (the two-scan construction, scalar flavor): every
/// stored cell contributes its full dense tile, so the pattern carries
/// the tiles' structural zeros (~1% on entity-block models) and needs
/// no COO pass. Returns the zero-valued matrix and the position
/// resolver for [`LmProblem::accumulate_hessian_positions`].
pub fn csc_from_cells<T: Float>(
    partition: &[usize],
    cells: &[(u32, u32)],
) -> (CscMatrix<T>, ScalarCscResolver) {
    let nblk = partition.len() - 1;
    let n = partition[nblk];
    let mut blk_of = vec![0u32; n];
    for b in 0..nblk {
        for i in partition[b]..partition[b + 1] {
            blk_of[i] = b as u32;
        }
    }

    // cell set, sorted by (block_col, block_row), run-compressed first
    let mut keys: std::vec::Vec<u64> = std::vec::Vec::with_capacity(1024);
    let mut last = u64::MAX;
    for &(i, j) in cells {
        let key = ((blk_of[j as usize] as u64) << 32) | blk_of[i as usize] as u64;
        if key != last {
            keys.push(key);
            last = key;
        }
    }
    keys.sort_unstable();
    keys.dedup();

    // per-cell row prefix within its block column; per-column nnz
    let mut prefix = vec![0usize; keys.len()];
    let mut col_ptr = vec![0usize; n + 1];
    {
        let mut c = 0;
        while c < keys.len() {
            let bc = (keys[c] >> 32) as usize;
            let mut acc = 0usize;
            let mut e = c;
            while e < keys.len() && (keys[e] >> 32) as usize == bc {
                let br = keys[e] as u32 as usize;
                prefix[e] = acc;
                acc += partition[br + 1] - partition[br];
                e += 1;
            }
            // every scalar column of this block column holds `acc` rows
            for j in partition[bc]..partition[bc + 1] {
                col_ptr[j + 1] = acc;
            }
            c = e;
        }
    }
    for j in 0..n {
        col_ptr[j + 1] += col_ptr[j];
    }

    // row indices: per block column, the tiles' row spans, repeated for
    // each scalar column; diagonal positions where the diagonal tile is
    // stored (0 otherwise -- degenerate model, matching to_csc)
    let nnz = col_ptr[n];
    let mut row_idx = std::vec::Vec::with_capacity(nnz);
    let mut diag_pos = vec![0usize; n];
    {
        let mut c = 0;
        while c < keys.len() {
            let bc = (keys[c] >> 32) as usize;
            let mut e = c;
            while e < keys.len() && (keys[e] >> 32) as usize == bc {
                e += 1;
            }
            for j in partition[bc]..partition[bc + 1] {
                for k in c..e {
                    let br = keys[k] as u32 as usize;
                    if br == bc {
                        diag_pos[j] = col_ptr[j] + prefix[k] + (j - partition[br]);
                    }
                    for i in partition[br]..partition[br + 1] {
                        row_idx.push(i as u32);
                    }
                }
            }
            c = e;
        }
    }

    let csc = CscMatrix {
        n,
        col_ptr: col_ptr.clone(),
        row_idx,
        vals: vec![T::zero(); nnz],
        diag_pos,
    };
    let resolver = ScalarCscResolver {
        col_ptr,
        row_part: partition.to_vec(),
        blk_of,
        keys,
        prefix,
        memo_key: u64::MAX,
        memo_prefix: 0,
        memo_row_start: 0,
    };
    (csc, resolver)
}

/// Turn entity spans (from [`RootProblem::param_block_spans`]) into a
/// full block partition of `0..n`: ascending scalar offsets with one
/// entry per block boundary, first 0, last `n`. Parameters not covered
/// by any entity span (e.g. `skip_self_block` models) become one block
/// per gap. Panics if spans overlap or run backwards.
pub fn block_partition_from_spans(spans: &[(u32, u32)], n: usize) -> std::vec::Vec<usize> {
    let mut part = std::vec::Vec::with_capacity(spans.len() + 2);
    part.push(0usize);
    let mut end = 0usize;
    for &(off, width) in spans {
        let off = off as usize;
        assert!(off >= end, "param block spans overlap or are unsorted");
        if off > end {
            // gap: params owned by no SelfBlock form their own block
            part.push(off);
        }
        end = off + width as usize;
        part.push(end);
    }
    assert!(end <= n);
    if end < n {
        part.push(n);
    }
    part
}

/// Entry points of an `#[arael(fit(...))]` / `#[arael(fit64(...))]` model.
/// The macro implements the parameter round trip (`serialize` /
/// `deserialize`); `fit` and `fit_with` are library-provided defaults
/// running the dense LM over it -- fit models assemble a small dense
/// Hessian and do not support the sparse/band backends, which is why they
/// carry their own entry points instead of [`RootProblem`]'s `solve_*`
/// family. `fit(...)` is f32; `fit64(...)` is f64.
pub trait FitProblem<T: Float>: LmProblem<T> + Sized {
    /// Flatten the optimizable parameters into `data`. The initial guess.
    fn serialize(&mut self, data: &mut Vec<T>);
    /// Write an optimized parameter vector back into the model.
    fn deserialize(&mut self, data: &[T]);

    /// Least-squares fit with the given config, wrapping the
    /// serialize -> dense LM -> deserialize round trip: parameters are
    /// read from the model and the optimized values written back.
    fn fit_with(&mut self, config: &LmConfig<T>) -> LmResult<T>
    where
        Dense: LmSolver<T>,
    {
        let mut params = Vec::new();
        self.serialize(&mut params);
        let result = lm_solve(&params, &mut Dense, self, config);
        self.deserialize(&result.x);
        result
    }

    /// [`fit_with`](Self::fit_with) under the default [`LmConfig`].
    fn fit(&mut self) -> LmResult<T>
    where
        Dense: LmSolver<T>,
    {
        self.fit_with(&LmConfig::default())
    }
}

/// Provides cost evaluation and gradient/Hessian assembly in various matrix
/// formats (dense, band, COO sparse, CSC sparse, indexed sparse), plus --
/// for types that also implement [`RootProblem`], i.e. every `#[arael(root)]`
/// model -- the solve entry points `solve_with` / `solve_dense` /
/// `solve_sparse` as default methods. Call them with the trait in scope:
/// `use arael::simple_lm::LmProblem;`.
pub trait LmProblem<T> {
    /// Evaluate the total cost at the given parameters.
    fn calc_cost(&mut self, params: &[T]) -> T;
    /// Assemble gradient and dense row-major Hessian (n*n). Returns the
    /// cost at `params` -- the residual values are in hand during assembly,
    /// so the cost is a free byproduct (macro-generated models compute it
    /// in the same sweep; hand-written impls should return it likewise).
    fn calc_grad_hessian_dense(&mut self, params: &[T], grad: &mut [T], hessian: &mut [T]) -> T;
    /// Assemble gradient and Hessian in upper-band format (column-major, (kd+1)*n).
    /// Returns the cost at `params`, or Err if any block exceeds the
    /// declared bandwidth kd.
    fn calc_grad_hessian_band(&mut self, params: &[T], grad: &mut [T], band: &mut [T], kd: usize) -> Result<T, BandError>;
    /// Assemble gradient and upper-triangle Hessian as COO triplets.
    /// Returns the cost at `params`.
    fn calc_grad_hessian_sparse(&mut self, params: &[T], grad: &mut [T], coo: &mut CooMatrix<T>) -> T;
    /// Assemble gradient and accumulate Hessian directly into CSC vals
    /// (structure must be pre-built). Returns the cost at `params`.
    fn calc_grad_hessian_sparse_direct(&mut self, params: &[T], grad: &mut [T], csc: &mut CscMatrix<T>) -> T;
    /// Assemble gradient and accumulate Hessian into CSC vals using a
    /// precomputed position map. Returns the cost at `params`.
    fn calc_grad_hessian_sparse_indexed(&mut self, params: &[T], grad: &mut [T], vals: &mut [T], positions: &[usize]) -> T;
    /// Called after each accepted LM step to let the problem update internal state.
    /// Default: no-op.
    fn advance(&mut self, _params: &mut [T]) {}

    /// Solve with the given [`LmSolver`] backend, wrapping the
    /// serialize -> optimize -> deserialize round trip: parameters are
    /// read from the model and the optimized values written back. The
    /// damping schedule comes from `config.driver` (set it with
    /// [`LmConfig::with_driver`]). For the common backends use
    /// [`solve_dense`](Self::solve_dense) or
    /// [`solve_sparse`](Self::solve_sparse).
    fn solve_with<S: LmSolver<T>>(&mut self, solver: &mut S, config: &LmConfig<T>) -> LmResult<T>
    where
        Self: RootProblem<T> + Sized,
        T: Float,
    {
        let mut params = Vec::new();
        self.serialize(&mut params);
        let result = lm_solve(&params, solver, self, config);
        self.deserialize(&result.x);
        result
    }

    /// Solve with the dense nalgebra Cholesky backend ([`Dense`]) --
    /// low parameter counts or genuinely dense problems. Convenience
    /// over [`solve_with`](Self::solve_with).
    fn solve_dense(&mut self, config: &LmConfig<T>) -> LmResult<T>
    where
        Self: RootProblem<T> + Sized,
        T: Float,
        Dense: LmSolver<T>,
    {
        self.solve_with(&mut Dense, config)
    }

    /// Whether the Hessian pattern is only discoverable by running a
    /// compute pass first (TripletBlock / extended-model constraints
    /// fill their entries at runtime). The pattern itself is frozen
    /// after the first iteration by contract for EVERY model -- this
    /// flag is about when it becomes knowable, not whether it changes.
    /// When `false`, the structure walks below are complete before any
    /// compute, and sparse backends may build their pattern without a
    /// COO discovery pass. Defaults to `true` (unknown = assume
    /// runtime-determined); the macro overrides it.
    fn hessian_pattern_requires_compute(&self) -> bool {
        true
    }
    /// Append one representative scalar coordinate per Hessian block
    /// cell (see `Model::collect_hessian_cells64`). Default: nothing
    /// (structure walk unsupported -- backends fall back to COO).
    fn collect_hessian_cells(&self, _out: &mut std::vec::Vec<(u32, u32)>) {}
    /// Push every Hessian scatter position in the exact emission order
    /// of [`calc_grad_hessian_sparse_indexed`](Self::calc_grad_hessian_sparse_indexed),
    /// resolving each scalar coordinate through `resolve`.
    fn accumulate_hessian_positions(
        &self,
        _resolve: &mut dyn FnMut(u32, u32) -> usize,
        _out: &mut std::vec::Vec<usize>,
    ) {}
    /// Append the entity parameter spans (see
    /// [`RootProblem::param_block_spans`]). Default: nothing.
    fn collect_param_block_spans(&self, _out: &mut std::vec::Vec<(u32, u32)>) {}

    /// Solve with the indexed sparse faer backend ([`SparseFaer`], pure
    /// Rust) -- the default choice for anything non-trivial. Convenience
    /// over [`solve_with`](Self::solve_with). The model's
    /// [`elimination hint`](RootProblem::elimination_hint) (from
    /// `#[arael(root, eliminate_first(field))]`) is wired into the solver
    /// automatically.
    fn solve_sparse(&mut self, config: &LmConfig<T>) -> LmResult<T>
    where
        Self: RootProblem<T> + Sized,
        T: Float,
        SparseFaer<T>: LmSolver<T>,
    {
        let mut solver = SparseFaer::<T>::new();
        for range in RootProblem::elimination_hint(self) {
            solver = solver.with_eliminate_first(range);
        }
        self.solve_with(&mut solver, config)
    }

    /// Solve with the Schur-complement faer backend ([`SparseFaerSchur`]):
    /// the model's `eliminate_first` blocks are marginalized on every
    /// damped solve and only the reduced system is factorized. Requires
    /// the hint and a statically-knowable Hessian pattern -- see
    /// [`SparseFaerSchur`] for the exact contract.
    fn solve_sparse_schur(&mut self, config: &LmConfig<T>) -> LmResult<T>
    where
        Self: RootProblem<T> + Sized,
        T: Float,
        SparseFaerSchur<T>: LmSolver<T>,
    {
        let mut solver = SparseFaerSchur::<T>::new();
        for range in RootProblem::elimination_hint(self) {
            solver = solver.with_eliminate_first(range);
        }
        self.solve_with(&mut solver, config)
    }
}

/// Adapter: wrap two closures into an LmProblem (dense only).
pub struct FnProblem<F1, F2> {
    /// Closure computing the scalar cost from parameters. Used for trial
    /// points during the LM damping search.
    pub cost: F1,
    /// Closure assembling gradient and dense Hessian from parameters,
    /// returning the cost (a free byproduct -- the residuals are in hand).
    pub grad_hessian: F2,
}

impl<T, F1, F2> LmProblem<T> for FnProblem<F1, F2>
where
    F1: FnMut(&[T]) -> T,
    F2: FnMut(&[T], &mut [T], &mut [T]) -> T,
{
    fn calc_cost(&mut self, params: &[T]) -> T {
        (self.cost)(params)
    }
    fn calc_grad_hessian_dense(&mut self, params: &[T], grad: &mut [T], hessian: &mut [T]) -> T {
        (self.grad_hessian)(params, grad, hessian)
    }
    fn calc_grad_hessian_band(&mut self, _params: &[T], _grad: &mut [T], _band: &mut [T], _kd: usize) -> Result<T, BandError> {
        unimplemented!("FnProblem does not support band assembly")
    }
    fn calc_grad_hessian_sparse(&mut self, _params: &[T], _grad: &mut [T], _coo: &mut CooMatrix<T>) -> T {
        unimplemented!("FnProblem does not support sparse assembly")
    }
    fn calc_grad_hessian_sparse_direct(&mut self, _params: &[T], _grad: &mut [T], _csc: &mut CscMatrix<T>) -> T {
        unimplemented!("FnProblem does not support sparse direct assembly")
    }
    fn calc_grad_hessian_sparse_indexed(&mut self, _params: &[T], _grad: &mut [T], _vals: &mut [T], _positions: &[usize]) -> T {
        unimplemented!("FnProblem does not support sparse indexed assembly")
    }
}

/// Why the Levenberg-Marquardt solver stopped (see [`LmResult::status`]).
/// Each variant is a distinct exit path in the solve loop.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LmStatus {
    /// Reached a minimum: `patience` consecutive small steps, the
    /// machine-precision noise floor, or a zero starting cost.
    Converged,
    /// Cost dropped to or below [`LmConfig::cost_threshold`].
    CostThreshold,
    /// Hit [`LmConfig::max_iters`] without meeting a convergence criterion.
    MaxIterations,
    /// The damping driver gave up -- lambda would pass its ceiling and no
    /// step could be accepted ([`LambdaDriver::rejected`] returned `None`).
    LambdaCeiling,
    /// 20 consecutive damped attempts failed to produce a cost-decreasing
    /// step (the hard inner-retry budget, distinct from `LambdaCeiling`).
    RetryBudgetExhausted,
    /// A parameter's Gauss-Newton Hessian diagonal was non-positive (no
    /// active constraint curvature reaches it, or assembly was poisoned by
    /// NaN). The solve returned the best parameters found so far.
    DegenerateDiagonal { param: usize },
}

/// Per-phase wall-clock timing gathered during a solve. Produced only when
/// [`LmConfig::gather_timing`] is set -- otherwise [`LmResult::timing`] is
/// `None` and the solver never reads the clock. Times are wall-clock,
/// single-threaded, and include only the work inside each phase (not the loop
/// bookkeeping between them), so the phase sums are slightly less than `total`.
#[derive(Clone, Debug, Default)]
pub struct LmTiming {
    /// Whole `lm_solve` wall clock, from the first assembly to the return.
    pub total: Duration,
    /// Gradient + Hessian assembly (residual, Jacobian, accumulation) summed
    /// over every iteration.
    pub assembly: Duration,
    /// The first assembly alone. It also discovers the sparsity pattern and
    /// builds the value-position map -- a one-time structure cost the steady
    /// state does not pay.
    pub first_assembly: Duration,
    /// Damped linear solve (factorization + triangular solve) summed over
    /// every inner attempt.
    pub linear_solve: Duration,
    /// The first damped solve alone. It also runs the symbolic factorization
    /// (fill-reducing ordering + elimination-tree structure) -- a one-time
    /// cost the steady state does not pay.
    pub first_linear_solve: Duration,
    /// Trial-point cost evaluation (residual only, no Jacobian) summed over
    /// every inner attempt.
    pub cost_eval: Duration,
    /// The first cost evaluation alone (recorded apart so the steady-state
    /// mean can drop the first iteration uniformly with the other phases).
    pub first_cost_eval: Duration,
    /// Post-step `advance` (parameter re-centering) summed over accepted steps.
    pub advance: Duration,
    /// The first `advance` alone (recorded apart so the steady-state mean can
    /// drop the first iteration uniformly with the other phases).
    pub first_advance: Duration,
    /// Number of assembly calls (one per outer iteration).
    pub assembly_count: usize,
    /// Number of damped-solve attempts (one per inner iteration that reached
    /// factorization).
    pub linear_solve_count: usize,
    /// Number of trial-point cost evaluations.
    pub cost_eval_count: usize,
    /// Number of `advance` calls (one per accepted step).
    pub advance_count: usize,
}

/// Mean of a phase's per-call time with the first call removed:
/// `(total - first) / (count - 1)`. Returns `None` when there is no call
/// after the first (`count <= 1`), so there is no steady state to average.
fn steady_mean(total: Duration, first: Duration, count: usize) -> Option<Duration> {
    if count <= 1 {
        return None;
    }
    Some((total - first) / (count as u32 - 1))
}

impl LmTiming {
    /// Mean assembly time per iteration, EXCLUDING the first. The first
    /// assembly also builds the sparsity pattern, so averaging it in would
    /// skew the steady-state estimate. `None` if the solve had only one
    /// assembly.
    pub fn mean_assembly(&self) -> Option<Duration> {
        steady_mean(self.assembly, self.first_assembly, self.assembly_count)
    }
    /// Mean damped-solve time per attempt, EXCLUDING the first (which also
    /// runs the symbolic factorization). `None` if there was only one solve.
    pub fn mean_linear_solve(&self) -> Option<Duration> {
        steady_mean(self.linear_solve, self.first_linear_solve, self.linear_solve_count)
    }
    /// Mean trial-point cost evaluation, EXCLUDING the first call. `None` if
    /// there was only one evaluation.
    pub fn mean_cost_eval(&self) -> Option<Duration> {
        steady_mean(self.cost_eval, self.first_cost_eval, self.cost_eval_count)
    }
    /// Mean re-centering (`advance`) time, EXCLUDING the first call. `None` if
    /// there was only one accepted step.
    pub fn mean_advance(&self) -> Option<Duration> {
        steady_mean(self.advance, self.first_advance, self.advance_count)
    }
}

/// Result returned by the Levenberg-Marquardt solver.
#[derive(Clone, Debug)]
pub struct LmResult<T> {
    /// Final parameter vector.
    pub x: Vec<T>,
    /// Cost at the initial parameters.
    pub start_cost: T,
    /// Cost at the final parameters.
    pub end_cost: T,
    /// Total number of iterations performed (including inner damping retries).
    pub iterations: usize,
    /// Number of ACCEPTED steps (cost-decreasing parameter updates).
    /// `iterations - accepted_iterations` is the damping-retry overhead:
    /// rejected trial steps and failed factorizations.
    pub accepted_iterations: usize,
    /// Why the solve stopped.
    pub status: LmStatus,
    /// The damping parameter lambda at exit. Seeds a warm restart or a
    /// follow-up solve that wants to resume from the same damping.
    pub final_lambda: T,
    /// Per-phase wall-clock timing: `Some` iff [`LmConfig::gather_timing`]
    /// was set, `None` otherwise (see [`LmTiming`]).
    pub timing: Option<LmTiming>,
}

// ---------------------------------------------------------------------------
// Cholesky solve — nalgebra fixed-size, dispatch by runtime n
// ---------------------------------------------------------------------------

fn cholesky_solve<const N: usize>(a: &[f64], b: &[f64], x: &mut [f64]) -> bool {
    let mat = nalgebra::SMatrix::<f64, N, N>::from_row_slice(a);
    let rhs = nalgebra::SVector::<f64, N>::from_column_slice(b);
    match nalgebra::linalg::Cholesky::new(mat) {
        Some(chol) => {
            let sol = chol.solve(&rhs);
            x.copy_from_slice(sol.as_slice());
            true
        }
        None => false,
    }
}

fn cholesky_solve_f32<const N: usize>(a: &[f32], b: &[f32], x: &mut [f32]) -> bool {
    let mat = nalgebra::SMatrix::<f32, N, N>::from_row_slice(a);
    let rhs = nalgebra::SVector::<f32, N>::from_column_slice(b);
    match nalgebra::linalg::Cholesky::new(mat) {
        Some(chol) => {
            let sol = chol.solve(&rhs);
            x.copy_from_slice(sol.as_slice());
            true
        }
        None => false,
    }
}

macro_rules! dispatch_cholesky {
    ($solve_fn:ident, $n:expr, $a:expr, $b:expr, $x:expr) => {
        match $n {
            1 => $solve_fn::<1>($a, $b, $x),
            2 => $solve_fn::<2>($a, $b, $x),
            3 => $solve_fn::<3>($a, $b, $x),
            4 => $solve_fn::<4>($a, $b, $x),
            5 => $solve_fn::<5>($a, $b, $x),
            6 => $solve_fn::<6>($a, $b, $x),
            7 => $solve_fn::<7>($a, $b, $x),
            8 => $solve_fn::<8>($a, $b, $x),
            9 => $solve_fn::<9>($a, $b, $x),
            _ => unreachable!(),
        }
    };
}

fn cholesky_solve_dynamic(n: usize, a: &[f64], b: &[f64], x: &mut [f64]) -> bool {
    let mat = nalgebra::DMatrix::from_row_slice(n, n, a);
    let rhs = nalgebra::DVector::from_column_slice(b);
    match nalgebra::linalg::Cholesky::new(mat) {
        Some(chol) => {
            let sol = chol.solve(&rhs);
            x.copy_from_slice(sol.as_slice());
            true
        }
        None => false,
    }
}

fn cholesky_solve_dynamic_f32(n: usize, a: &[f32], b: &[f32], x: &mut [f32]) -> bool {
    let mat = nalgebra::DMatrix::from_row_slice(n, n, a);
    let rhs = nalgebra::DVector::from_column_slice(b);
    match nalgebra::linalg::Cholesky::new(mat) {
        Some(chol) => {
            let sol = chol.solve(&rhs);
            x.copy_from_slice(sol.as_slice());
            true
        }
        None => false,
    }
}

/// Solve A*x = b for symmetric positive definite A (f64) via Cholesky decomposition.
/// Uses fixed-size nalgebra for n <= 9, dynamic allocation otherwise.
/// Returns false if A is not positive definite.
pub fn solve_spd(n: usize, a: &[f64], b: &[f64], x: &mut [f64]) -> bool {
    if n <= 9 {
        dispatch_cholesky!(cholesky_solve, n, a, b, x)
    } else {
        cholesky_solve_dynamic(n, a, b, x)
    }
}

/// Solve A*x = b for symmetric positive definite A (f32) via Cholesky decomposition.
/// Uses fixed-size nalgebra for n <= 9, dynamic allocation otherwise.
/// Returns false if A is not positive definite.
pub fn solve_spd_f32(n: usize, a: &[f32], b: &[f32], x: &mut [f32]) -> bool {
    if n <= 9 {
        dispatch_cholesky!(cholesky_solve_f32, n, a, b, x)
    } else {
        cholesky_solve_dynamic_f32(n, a, b, x)
    }
}

// ---------------------------------------------------------------------------
// LmSolver trait — abstract over matrix storage and linear solve
// ---------------------------------------------------------------------------

/// Abstract linear algebra backend for the LM solver.
///
/// Assembles and solves the damped normal equations using a specific matrix
/// storage format (dense, band, sparse, etc.).
pub trait LmSolver<T: Float> {
    /// Associated matrix storage type (e.g. Vec for dense, SparseMatrix for sparse).
    type Matrix;

    /// Create a zero-initialized matrix for n parameters.
    fn new_matrix(&self, n: usize) -> Self::Matrix;

    /// Compute gradient and Hessian matrix from the problem. Returns the
    /// cost at `params` (a free byproduct of assembly); the LM loop uses
    /// it for the first evaluation of a solve.
    fn compute(&mut self, problem: &mut dyn LmProblem<T>, params: &[T], grad: &mut [T], matrix: &mut Self::Matrix) -> T;

    /// Extract all diagonal elements from the matrix.
    fn extract_diagonal(&self, matrix: &Self::Matrix, diagonal: &mut [T]);

    /// Apply LM damping and solve: sets diagonal to (1+lambda)*saved_diag, then solves.
    /// Returns false if the system is not positive definite.
    fn solve_damped(&mut self, n: usize, matrix: &mut Self::Matrix, diagonal: &[T], lambda: T, grad: &[T], delta: &mut [T]) -> bool;

    /// Count non-finite (NaN / inf) entries in the matrix. Used by the
    /// main loop for diagnostic output when Cholesky rejects a solve.
    /// No default -- every solver must scan its own storage so the
    /// diagnostic can never silently lie.
    fn matrix_nonfinite_count(&self, matrix: &Self::Matrix) -> usize;

    /// Drop all cached problem structure (sparsity patterns, symbolic
    /// factorizations, position maps) so the solver behaves like a
    /// freshly constructed one. Called by `lm_solve` at entry, making
    /// solver reuse across solves safe: caches are only ever valid
    /// within one solve. No default -- every backend must state what
    /// it caches, so a future cache cannot silently outlive a solve.
    fn reset(&mut self);
}

/// Dense Cholesky solver (nalgebra).
///
/// The per-retry DMatrix copy is deliberate: it is O(n^2) under an
/// O(n^3) blocked factorization, and replacing nalgebra with a naive
/// in-place scalar Cholesky to avoid it measured 5x SLOWER at n = 3000
/// (P6 investigation) -- the allocation was never the cost.
pub struct Dense;

impl LmSolver<f64> for Dense {
    type Matrix = Vec<f64>;
    fn new_matrix(&self, n: usize) -> Vec<f64> { vec![0.0; n * n] }
    fn compute(&mut self, problem: &mut dyn LmProblem<f64>, params: &[f64], grad: &mut [f64], hessian: &mut Vec<f64>) -> f64 {
        problem.calc_grad_hessian_dense(params, grad, hessian)
    }
    fn extract_diagonal(&self, matrix: &Vec<f64>, diagonal: &mut [f64]) {
        let n = diagonal.len();
        for i in 0..n { diagonal[i] = matrix[i * n + i]; }
    }
    fn solve_damped(&mut self, n: usize, matrix: &mut Vec<f64>, diagonal: &[f64], lambda: f64, grad: &[f64], delta: &mut [f64]) -> bool {
        for i in 0..n { matrix[i * n + i] = (1.0 + lambda) * diagonal[i]; }
        solve_spd(n, matrix, grad, delta)
    }
    fn matrix_nonfinite_count(&self, matrix: &Vec<f64>) -> usize {
        matrix.iter().filter(|v| !v.is_finite()).count()
    }
    fn reset(&mut self) {} // stateless: no cached problem structure
}

impl LmSolver<f32> for Dense {
    type Matrix = Vec<f32>;
    fn new_matrix(&self, n: usize) -> Vec<f32> { vec![0.0; n * n] }
    fn compute(&mut self, problem: &mut dyn LmProblem<f32>, params: &[f32], grad: &mut [f32], hessian: &mut Vec<f32>) -> f32 {
        problem.calc_grad_hessian_dense(params, grad, hessian)
    }
    fn extract_diagonal(&self, matrix: &Vec<f32>, diagonal: &mut [f32]) {
        let n = diagonal.len();
        for i in 0..n { diagonal[i] = matrix[i * n + i]; }
    }
    fn solve_damped(&mut self, n: usize, matrix: &mut Vec<f32>, diagonal: &[f32], lambda: f32, grad: &[f32], delta: &mut [f32]) -> bool {
        for i in 0..n { matrix[i * n + i] = (1.0 + lambda) * diagonal[i]; }
        solve_spd_f32(n, matrix, grad, delta)
    }
    fn matrix_nonfinite_count(&self, matrix: &Vec<f32>) -> usize {
        matrix.iter().filter(|v| !v.is_finite()).count()
    }
    fn reset(&mut self) {} // stateless: no cached problem structure
}

/// Band Cholesky solver (pure Rust).
pub struct Band {
    /// Half-bandwidth (number of superdiagonals).
    pub kd: usize,
    // Retry scratch: band Cholesky destroys its input, so each damped
    // attempt factors a copy. Reusing one buffer avoids an allocation
    // per lambda retry. Fully overwritten before every use -- carries
    // no state across retries or solves.
    scratch64: Vec<f64>,
    scratch32: Vec<f32>,
}

impl Band {
    /// Create a band solver with the given half-bandwidth.
    pub fn new(kd: usize) -> Band {
        Band { kd, scratch64: Vec::new(), scratch32: Vec::new() }
    }
}

impl LmSolver<f64> for Band {
    type Matrix = Vec<f64>;
    fn new_matrix(&self, n: usize) -> Vec<f64> { vec![0.0; (self.kd + 1) * n] }
    fn compute(&mut self, problem: &mut dyn LmProblem<f64>, params: &[f64], grad: &mut [f64], band: &mut Vec<f64>) -> f64 {
        problem.calc_grad_hessian_band(params, grad, band, self.kd)
            .expect("band assembly failed: element outside bandwidth")
    }
    fn extract_diagonal(&self, matrix: &Vec<f64>, diagonal: &mut [f64]) {
        let ldab = self.kd + 1;
        for i in 0..diagonal.len() { diagonal[i] = matrix[self.kd + i * ldab]; }
    }
    fn solve_damped(&mut self, n: usize, matrix: &mut Vec<f64>, diagonal: &[f64], lambda: f64, grad: &[f64], delta: &mut [f64]) -> bool {
        // Band Cholesky destroys the matrix, so factor a copy -- in the
        // reused scratch buffer, not a fresh allocation per retry.
        let ldab = self.kd + 1;
        self.scratch64.resize(matrix.len(), 0.0);
        self.scratch64.copy_from_slice(matrix);
        for i in 0..n { self.scratch64[self.kd + i * ldab] = (1.0 + lambda) * diagonal[i]; }
        delta.copy_from_slice(grad);
        solve_spd_band(n, self.kd, &mut self.scratch64, delta)
    }
    fn matrix_nonfinite_count(&self, matrix: &Vec<f64>) -> usize {
        matrix.iter().filter(|v| !v.is_finite()).count()
    }
    fn reset(&mut self) {} // scratch is fully overwritten each use: no cross-solve state
}

impl LmSolver<f32> for Band {
    type Matrix = Vec<f32>;
    fn new_matrix(&self, n: usize) -> Vec<f32> { vec![0.0; (self.kd + 1) * n] }
    fn compute(&mut self, problem: &mut dyn LmProblem<f32>, params: &[f32], grad: &mut [f32], band: &mut Vec<f32>) -> f32 {
        problem.calc_grad_hessian_band(params, grad, band, self.kd)
            .expect("band assembly failed: element outside bandwidth")
    }
    fn extract_diagonal(&self, matrix: &Vec<f32>, diagonal: &mut [f32]) {
        let ldab = self.kd + 1;
        for i in 0..diagonal.len() { diagonal[i] = matrix[self.kd + i * ldab]; }
    }
    fn solve_damped(&mut self, n: usize, matrix: &mut Vec<f32>, diagonal: &[f32], lambda: f32, grad: &[f32], delta: &mut [f32]) -> bool {
        let ldab = self.kd + 1;
        self.scratch32.resize(matrix.len(), 0.0);
        self.scratch32.copy_from_slice(matrix);
        for i in 0..n { self.scratch32[self.kd + i * ldab] = (1.0 + lambda) * diagonal[i]; }
        delta.copy_from_slice(grad);
        solve_spd_band_f32(n, self.kd, &mut self.scratch32, delta)
    }
    fn matrix_nonfinite_count(&self, matrix: &Vec<f32>) -> usize {
        matrix.iter().filter(|v| !v.is_finite()).count()
    }
    fn reset(&mut self) {} // scratch is fully overwritten each use: no cross-solve state
}

