// ---------------------------------------------------------------------------
// Generic LM solver
// ---------------------------------------------------------------------------

/// Default damping floor for the LM accept path: the named 1e-12,
/// raised to machine epsilon where 1e-12 is not representable
/// meaningfully (f32). One mechanism -- this replaced a floor-guarded
/// decrement plus a separate epsilon clamp whose interaction put the
/// real f64 floor anywhere in [2e-13, 1e-12] depending on approach
/// path. Overridable per solve via `LmConfig::lambda_floor`.
fn default_lambda_floor<T: Float>() -> T {
    T::from(1e-12).unwrap().max(T::epsilon())
}

/// Lambda update after an accepted step: decrease, clamped to the floor.
fn lambda_after_accept<T: Float>(lambda: T, down: T, floor: T) -> T {
    (lambda * down).max(floor)
}

// ---------------------------------------------------------------------------
// Lambda drivers -- damping-schedule strategies for the LM loop
// ---------------------------------------------------------------------------

/// The solve state a [`LambdaDriver`] sees at solve start and on
/// factorization failures: everything the loop has in hand at the
/// current linearization point.
pub struct LambdaState<'a, T> {
    /// Cost (sum of squared residuals) at the linearization point.
    pub cost: T,
    /// Gradient at the linearization point.
    pub grad: &'a [T],
    /// Gauss-Newton Hessian diagonal at the linearization point.
    pub diagonal: &'a [T],
}

/// Data the LM loop reports to a [`LambdaDriver`] about one attempted step.
pub struct LambdaStep<'a, T> {
    /// The lambda this step was attempted with.
    pub lambda: T,
    /// Cost (sum of squared residuals) before the step.
    pub cost: T,
    /// Cost at the attempted parameters.
    pub new_cost: T,
    /// Gradient at the linearization point the step was computed from.
    pub grad: &'a [T],
    /// Gauss-Newton Hessian diagonal at the same linearization point.
    pub diagonal: &'a [T],
    /// The attempted step vector (`x_new = x - delta`).
    pub delta: &'a [T],
}

/// Damping-schedule strategy for the LM loop ("lambda driver").
///
/// The solver consults the driver for every lambda decision and feeds it
/// each attempted step's outcome (costs, gradient, Hessian diagonal, and
/// the attempted step vector), so a driver can be as simple as fixed
/// multipliers ([`DefaultLambdaDriver`]) or adapt to measured step
/// quality ([`NielsenLambdaDriver`]). Drivers are stateful; use a fresh
/// instance per solve.
/// A driver lives on the [`LmConfig`] (`config.driver`); set it with
/// [`LmConfig::with_driver`]. The plain entry points use the config's
/// driver, which defaults to [`DefaultLambdaDriver`].
pub trait LambdaDriver<T: Float>: LambdaDriverClone<T> {
    /// Called once at solve start, after the first assembly (so the
    /// initial cost, gradient and Hessian diagonal are available);
    /// returns the initial lambda.
    fn start(&mut self, config: &LmConfig<T>, state: &LambdaState<T>) -> T;
    /// The step was accepted (cost decreased); returns the lambda for the
    /// next iteration.
    fn accepted(&mut self, step: &LambdaStep<T>) -> T;
    /// The step was rejected (cost did not decrease); returns the lambda
    /// for the retry, or `None` to abandon the solve (the schedule sees
    /// no viable damping left -- the loop terminates as if its retry
    /// budget were exhausted).
    fn rejected(&mut self, step: &LambdaStep<T>) -> Option<T>;
    /// The damped normal equations could not be factorized at `lambda`
    /// (not positive definite); returns the lambda for the retry.
    fn factorization_failed(&mut self, lambda: T, state: &LambdaState<T>) -> T;
}

/// Clone helper that lets the boxed driver an [`LmConfig`] carries be
/// cloned (each solve works on a fresh clone, leaving the shared config
/// untouched). Auto-implemented for every `Clone` driver; you never
/// implement it by hand -- just `#[derive(Clone)]` your driver.
pub trait LambdaDriverClone<T> {
    /// Clone `self` into a fresh boxed driver.
    fn clone_box(&self) -> Box<dyn LambdaDriver<T>>;
}

impl<T: Float, D: LambdaDriver<T> + Clone + 'static> LambdaDriverClone<T> for D {
    fn clone_box(&self) -> Box<dyn LambdaDriver<T>> {
        Box::new(self.clone())
    }
}

impl<T: Float> Clone for Box<dyn LambdaDriver<T>> {
    fn clone(&self) -> Self {
        self.clone_box()
    }
}

/// The classic fixed-multiplier schedule (the library default): divide
/// lambda by 5 on acceptance (clamped to `LmConfig::lambda_floor`),
/// multiply by 10 on rejection or factorization failure, and give up
/// when a rejection would push lambda past 1e10.
#[derive(Clone)]
pub struct DefaultLambdaDriver<T> {
    floor: T,
    ceiling: T,
    down: T,
    up: T,
}

impl<T: Float> Default for DefaultLambdaDriver<T> {
    fn default() -> Self {
        DefaultLambdaDriver {
            floor: default_lambda_floor::<T>(),
            ceiling: T::from(1e10).unwrap(),
            down: T::from(0.2).unwrap(),
            up: T::from(10.0).unwrap(),
        }
    }
}

impl<T: Float> LambdaDriver<T> for DefaultLambdaDriver<T> {
    fn start(&mut self, config: &LmConfig<T>, _state: &LambdaState<T>) -> T {
        self.floor = config.lambda_floor.max(T::epsilon());
        config.initial_lambda
    }
    fn accepted(&mut self, step: &LambdaStep<T>) -> T {
        lambda_after_accept(step.lambda, self.down, self.floor)
    }
    fn rejected(&mut self, step: &LambdaStep<T>) -> Option<T> {
        let next = step.lambda * self.up;
        if next > self.ceiling { None } else { Some(next) }
    }
    fn factorization_failed(&mut self, lambda: T, _state: &LambdaState<T>) -> T {
        lambda * self.up
    }
}

/// Gain-ratio adaptive damping (the Nielsen update).
///
/// After every accepted step the gain ratio
/// `rho = actual reduction / predicted reduction` measures how well the
/// linear model predicted reality, and lambda is scaled by
/// `max(1/3, 1 - (2 rho - 1)^3)`: a near-perfect model (rho ~ 1) cuts
/// lambda hard toward Gauss-Newton, a barely-accepted step (rho ~ 0)
/// raises it. Rejections multiply lambda by an escalating factor `nu`
/// (2, 4, 8, ...) that resets to 2 on the next acceptance, so recovery
/// from a bad region is geometric rather than a fixed-rate sawtooth.
/// This is the schedule from Nielsen, "Damping Parameter in Marquardt's
/// Method" (IMM-REP-1999-05), as popularized by Madsen/Nielsen/Tingleff;
/// it removes the oscillation the fixed schedule shows on strongly
/// nonlinear problems (bundle adjustment), where dividing lambda by a
/// constant after every acceptance marches straight into the next
/// rejection.
///
/// Respects `LmConfig::lambda_floor` on the way down and gives up above
/// the same 1e10 ceiling as the default schedule.
#[derive(Clone)]
pub struct NielsenLambdaDriver<T> {
    nu: T,
    floor: T,
    ceiling: T,
}

impl<T: Float> Default for NielsenLambdaDriver<T> {
    fn default() -> Self {
        NielsenLambdaDriver {
            nu: T::from(2.0).unwrap(),
            floor: default_lambda_floor::<T>(),
            ceiling: T::from(1e10).unwrap(),
        }
    }
}

impl<T: Float> NielsenLambdaDriver<T> {
    fn escalate(&mut self, lambda: T) -> T {
        let next = lambda * self.nu;
        self.nu = self.nu * T::from(2.0).unwrap();
        next
    }
}

impl<T: Float> LambdaDriver<T> for NielsenLambdaDriver<T> {
    fn start(&mut self, config: &LmConfig<T>, _state: &LambdaState<T>) -> T {
        self.floor = config.lambda_floor.max(T::epsilon());
        self.nu = T::from(2.0).unwrap();
        config.initial_lambda
    }
    fn accepted(&mut self, step: &LambdaStep<T>) -> T {
        self.nu = T::from(2.0).unwrap();
        // The linear model's predicted cost reduction. grad and the
        // Hessian diagonal are the true derivatives of the cost (the
        // generated blocks accumulate 2 J^T r / 2 J^T J for
        // cost = sum r^2), so with (H + lambda D) delta = g and
        // x_new = x - delta the model predicts a drop of
        // (delta.g + lambda delta.D.delta) / 2.
        let mut predicted = T::zero();
        for i in 0..step.delta.len() {
            predicted += step.delta[i]
                * (step.grad[i] + step.lambda * step.diagonal[i] * step.delta[i]);
        }
        predicted = predicted * T::from(0.5).unwrap();
        // Guard degenerate model predictions (zero or negative predicted
        // reduction on an ACCEPTED step is numerical noise near the
        // optimum): treat as a perfectly modeled step.
        let rho = if predicted > T::epsilon() {
            (step.cost - step.new_cost) / predicted
        } else {
            T::one()
        };
        let x = T::from(2.0).unwrap() * rho - T::one();
        let factor = (T::one() - x * x * x).max(T::from(1.0 / 3.0).unwrap());
        (step.lambda * factor).max(self.floor)
    }
    fn rejected(&mut self, step: &LambdaStep<T>) -> Option<T> {
        let next = self.escalate(step.lambda);
        if next > self.ceiling { None } else { Some(next) }
    }
    fn factorization_failed(&mut self, lambda: T, _state: &LambdaState<T>) -> T {
        self.escalate(lambda)
    }
}

/// Run Levenberg-Marquardt optimization with the given solver backend.
/// The damping schedule comes from `config.driver` (see [`LambdaDriver`];
/// defaults to [`DefaultLambdaDriver`], set another with
/// [`LmConfig::with_driver`]).
pub fn lm_solve<T: Float, S: LmSolver<T>>(
    x0: &[T],
    solver: &mut S,
    problem: &mut impl LmProblem<T>,
    config: &LmConfig<T>,
) -> LmResult<T> {
    // Drivers are stateful per solve; clone the config's prototype so the
    // shared config is untouched and a reused config starts each solve clean.
    let mut driver = config.driver.clone_box();
    let n = x0.len();
    if n == 0 {
        return LmResult {
            x: x0.to_vec(), start_cost: T::zero(), end_cost: T::zero(),
            iterations: 0, accepted_iterations: 0,
            status: LmStatus::Converged, final_lambda: T::zero(),
            timing: config.gather_timing.then(LmTiming::default),
        };
    }

    // Solver caches (sparsity pattern, symbolic factorization) are only
    // valid within a single solve; drop them so reused solver instances
    // behave identically to fresh ones. No-op on a fresh solver.
    solver.reset();

    let mut cur_x = x0.to_vec();
    let mut try_x = vec![T::zero(); n];
    let mut grad = vec![T::zero(); n];
    let mut matrix = solver.new_matrix(n);
    let mut diagonal = vec![T::zero(); n];
    let mut delta = vec![T::zero(); n];

    let eight = T::from(8.0).unwrap();

    // Set by driver.start() after the first assembly (so the driver
    // sees the initial cost, gradient, and Hessian diagonal).
    let mut lambda = T::zero();
    let mut started = false;
    let mut start_cost = T::zero();
    let mut end_cost = T::zero();

    let mut small_count = 0usize;
    // The exit reason. Defaults to MaxIterations; each convergence or
    // early-stop path overwrites it before breaking out of the loop.
    let mut status = LmStatus::MaxIterations;
    let mut done = false;
    let mut iter = 0usize;
    let mut accepted = 0usize;
    let mut first = true;
    let mut timer = Instant::now();

    // Per-phase timing. Only read the clock when the caller asked for it
    // (config.gather_timing) -- otherwise `gather.then(Instant::now)` is None
    // and no clock call happens at all.
    let gather = config.gather_timing;
    let mut timing = LmTiming::default();
    let solve_start = gather.then(Instant::now);

    while iter < config.max_iters && !done {
        let t_asm = gather.then(Instant::now);
        let computed_cost = solver.compute(problem, &cur_x, &mut grad, &mut matrix);
        if let Some(t) = t_asm {
            let dt = t.elapsed();
            if timing.assembly_count == 0 { timing.first_assembly = dt; }
            timing.assembly += dt;
            timing.assembly_count += 1;
        }
        if first {
            // The cost is a free byproduct of assembly; using it here
            // replaces the separate calc_cost(x0) pass of the old loop.
            first = false;
            start_cost = computed_cost;
            end_cost = computed_cost;
            // Already at zero cost — nothing to do
            if start_cost == T::zero() {
                if let Some(s) = solve_start { timing.total = s.elapsed(); }
                return LmResult { x: cur_x, start_cost, end_cost, iterations: 0,
                    accepted_iterations: 0, status: LmStatus::Converged, final_lambda: lambda,
                    timing: gather.then_some(timing) };
            }
        }
        solver.extract_diagonal(&matrix, &mut diagonal);
        // A non-positive diagonal cannot be rescued by multiplicative
        // damping ((1 + lambda) * 0 stays 0): the matrix is singular, no
        // step can ever be accepted, and the iteration would burn all its
        // inner failures against max_iters with no error indication. The
        // Gauss-Newton diagonal is a sum of squares, so zero means no
        // active constraint curvature touches the parameter at this
        // linearization point; NaN means poisoned assembly. !(d > 0)
        // catches both. This is a runtime value condition (a guard or
        // saturated robustifier can produce it from data), so it
        // terminates the solve loudly instead of panicking; structural
        // degeneracy (missing diagonal ENTRY) panics at CSC build time.
        // Reported as LmStatus::DegenerateDiagonal on the returned result.
        for (i, d) in diagonal.iter().enumerate() {
            if !(*d > T::zero()) {
                error!("arael::lm_solve: parameter {} has non-positive Hessian \
                        diagonal ({:?}) at iteration {}; no active constraint \
                        curvature touches it (degenerate model) -- terminating solve",
                    i, d.to_f64(), iter);
                if let Some(s) = solve_start { timing.total = s.elapsed(); }
                return LmResult { x: cur_x, start_cost, end_cost, iterations: iter,
                    accepted_iterations: accepted,
                    status: LmStatus::DegenerateDiagonal { param: i }, final_lambda: lambda,
                    timing: gather.then_some(timing) };
            }
        }

        if !started {
            started = true;
            lambda = driver.start(config, &LambdaState {
                cost: end_cost, grad: &grad, diagonal: &diagonal,
            });
        }

        let mut inner = 0usize;
        const INNER_LOOPS: usize = 20;

        while inner < INNER_LOOPS && iter < config.max_iters {
            iter += 1;

            let t_ls = gather.then(Instant::now);
            let solved = solver.solve_damped(n, &mut matrix, &diagonal, lambda, &grad, &mut delta);
            if let Some(t) = t_ls {
                let dt = t.elapsed();
                // The first solve also runs the symbolic factorization
                // (fill-reducing ordering + structure); record it apart.
                if timing.linear_solve_count == 0 { timing.first_linear_solve = dt; }
                timing.linear_solve += dt;
                timing.linear_solve_count += 1;
            }
            if !solved {
                let next_lambda = driver.factorization_failed(lambda, &LambdaState {
                    cost: end_cost, grad: &grad, diagonal: &diagonal,
                });
                if config.verbose {
                    let step_us = timer.elapsed().as_micros();
                    timer = Instant::now();
                    let n_nan_g = grad.iter().filter(|v| !v.is_finite()).count();
                    let n_nan_d = diagonal.iter().filter(|v| !v.is_finite()).count();
                    let n_nan_x = cur_x.iter().filter(|v| !v.is_finite()).count();
                    let n_nan_m = solver.matrix_nonfinite_count(&matrix);
                    // Non-positive diagonals are ruled out by the explicit
                    // check before the inner loop, so a failure here is
                    // off-diagonal indefiniteness or tiny-lambda rounding.
                    eprintln!("{}/{}: Cholesky failed (damped matrix not positive-definite), lambda={} -> {} (step={}) [non-finite: grad={} diag={} x={} matrix={}]",
                        iter, inner,
                        G(lambda.to_f64().unwrap()),
                        G(next_lambda.to_f64().unwrap()),
                        step_us,
                        n_nan_g, n_nan_d, n_nan_x, n_nan_m);
                }
                lambda = next_lambda;
                inner += 1;
                continue;
            }

            for i in 0..n {
                try_x[i] = cur_x[i] - delta[i];
            }

            let t_cost = gather.then(Instant::now);
            let new_cost = problem.calc_cost(&try_x);
            if let Some(t) = t_cost {
                let dt = t.elapsed();
                if timing.cost_eval_count == 0 { timing.first_cost_eval = dt; }
                timing.cost_eval += dt;
                timing.cost_eval_count += 1;
            }

            if config.verbose {
                let step_us = timer.elapsed().as_micros();
                timer = Instant::now();
                eprintln!("{}/{}: {}->{} / {}, lambda={} (step={})",
                    iter, inner,
                    G(end_cost.to_f64().unwrap()), G(new_cost.to_f64().unwrap()),
                    G((end_cost - new_cost).to_f64().unwrap()), G(lambda.to_f64().unwrap()),
                    step_us);
            }

            // At machine precision, cost differences are just rounding noise
            let at_precision = new_cost.is_finite()
                && (end_cost - new_cost).abs() < eight * T::epsilon() * end_cost.abs();

            if new_cost.is_finite() && new_cost < end_cost {
                accepted += 1;
                lambda = driver.accepted(&LambdaStep {
                    lambda, cost: end_cost, new_cost,
                    grad: &grad, diagonal: &diagonal, delta: &delta,
                });
                cur_x.copy_from_slice(&try_x);
                let t_adv = gather.then(Instant::now);
                problem.advance(&mut cur_x);
                if let Some(t) = t_adv {
                    let dt = t.elapsed();
                    if timing.advance_count == 0 { timing.first_advance = dt; }
                    timing.advance += dt;
                    timing.advance_count += 1;
                }

                // Cost reached target threshold -- terminate (respects min_iters)
                if iter >= config.min_iters && new_cost <= config.cost_threshold {
                    end_cost = new_cost;
                    status = LmStatus::CostThreshold;
                    done = true;
                    break;
                }

                let abs_improve = end_cost - new_cost;
                let rel_improve = if end_cost > T::epsilon() {
                    abs_improve / end_cost
                } else {
                    T::zero()
                };
                // A step is "small" if EITHER the absolute improvement is
                // negligible OR the relative improvement is negligible.
                // This way abs_precision alone can stop when cost is tiny,
                // and rel_precision alone can stop when the solver plateaus
                // at a larger cost.
                let is_small = abs_improve < config.abs_precision
                    || rel_improve < config.rel_precision;
                if iter >= config.min_iters && is_small {
                    small_count += 1;
                    if small_count >= config.patience {
                        status = LmStatus::Converged;
                        done = true;
                    }
                } else {
                    small_count = 0;
                }
                end_cost = new_cost;
                break;
            }

            if at_precision {
                status = LmStatus::Converged;
                done = true;
                break;
            }

            match driver.rejected(&LambdaStep {
                lambda, cost: end_cost, new_cost,
                grad: &grad, diagonal: &diagonal, delta: &delta,
            }) {
                Some(next) => lambda = next,
                None => {
                    // The driver gave up (lambda past its ceiling):
                    // terminate like an exhausted retry budget.
                    status = LmStatus::LambdaCeiling;
                    inner = INNER_LOOPS;
                    break;
                }
            }

            inner += 1;
        }
        if inner >= INNER_LOOPS && !done {
            // Distinguish the hard 20-retry cap from the driver's lambda
            // ceiling (the None branch above already set LambdaCeiling).
            if status == LmStatus::MaxIterations {
                status = LmStatus::RetryBudgetExhausted;
            }
            if config.verbose {
                eprintln!("LM terminated: {} consecutive inner steps without improvement (lambda={}, cost={})",
                    INNER_LOOPS,
                    G(lambda.to_f64().unwrap()),
                    G(end_cost.to_f64().unwrap()));
            }
            break;
        }
    }

    if let Some(s) = solve_start { timing.total = s.elapsed(); }
    LmResult {
        x: cur_x,
        start_cost,
        end_cost,
        iterations: iter,
        accepted_iterations: accepted,
        status,
        final_lambda: lambda,
        timing: gather.then_some(timing),
    }
}

